changeSet.sql:
SELECT set_config('vereint.rls_bypass', 'on', true);
CREATE TEMP TABLE series_chat_merge ON COMMIT DROP AS SELECT c.id AS conversation_id, e.series_id, FIRST_VALUE(c.id) OVER (PARTITION BY e.series_id ORDER BY c.created_at, c.id) AS target_id FROM conversations c JOIN events e ON e.id = c.event_id WHERE c.type = 'event' AND e.series_id IS NOT NULL;
UPDATE chat_messages m SET conversation_id = s.target_id FROM series_chat_merge s WHERE m.conversation_id = s.conversation_id AND s.conversation_id <> s.target_id;
UPDATE chat_media m SET conversation_id = s.target_id FROM series_chat_merge s WHERE m.conversation_id = s.conversation_id AND s.conversation_id <> s.target_id;
UPDATE conversation_members t SET last_read_at = GREATEST(t.last_read_at, o.last_read_at), last_delivered_at = GREATEST(t.last_delivered_at, o.last_delivered_at) FROM conversation_members o JOIN series_chat_merge s ON s.conversation_id = o.conversation_id WHERE s.conversation_id <> s.target_id AND t.conversation_id = s.target_id AND o.user_id IS NOT NULL AND t.user_id = o.user_id;
DELETE FROM conversation_members o USING series_chat_merge s WHERE o.conversation_id = s.conversation_id AND s.conversation_id <> s.target_id AND EXISTS ( SELECT 1 FROM conversation_members t WHERE t.conversation_id = s.target_id AND ((o.user_id IS NOT NULL AND t.user_id = o.user_id) OR (o.guest_id IS NOT NULL AND t.guest_id = o.guest_id)));
-- Dieselbe Person kann in mehreren Termin-Chats stehen: nur eine Zeile umziehen. DELETE FROM conversation_members o USING series_chat_merge s WHERE o.conversation_id = s.conversation_id AND s.conversation_id <> s.target_id AND EXISTS ( SELECT 1 FROM conversation_members d JOIN series_chat_merge ds ON ds.conversation_id = d.conversation_id WHERE ds.target_id = s.target_id AND ds.conversation_id <> ds.target_id AND d.id < o.id AND ((o.user_id IS NOT NULL AND d.user_id = o.user_id) OR (o.guest_id IS NOT NULL AND d.guest_id = o.guest_id)));
UPDATE conversation_members o SET conversation_id = s.target_id FROM series_chat_merge s WHERE o.conversation_id = s.conversation_id AND s.conversation_id <> s.target_id;
DELETE FROM conversations c USING series_chat_merge s WHERE c.id = s.conversation_id AND s.conversation_id <> s.target_id;
UPDATE conversations c SET series_id = s.series_id, event_id = NULL, direct_key = 'series:' || s.series_id, title = es.title FROM series_chat_merge s JOIN event_series es ON es.id = s.series_id WHERE c.id = s.target_id AND s.conversation_id = s.target_id;
